        Dish("可乐鸡翅", "晚餐", "菜", "甜", "零失败的下饭神器", 350, 25, "普通", "鸡中翅 8 个焯水冲净\n热锅少油，鸡翅两面煎到金黄\n倒入可乐 1 罐（约 200ml）没过鸡翅，加生抽 1 勺\n中火焖 15 分钟，大火收汁至浓稠裹住鸡翅", "默认池", "#粤菜家常"),
        Dish("清炒荷兰豆", "中餐", "菜", "淡", "清甜爽脆，配肉解腻", 90, 8, "普通", "荷兰豆撕去两头老筋，洗净\n水开加少许油盐焯 30 秒捞出\n热锅下油，大火快炒荷兰豆\n加盐少许兜匀，别炒久，要脆绿", "默认池", "#粤菜家常"),
        Dish("虾皮炒冬瓜", "中餐", "菜", "鲜", "清爽少油，夏天常做", 70, 15, "普通", "冬瓜 300g 去皮切片，虾皮 1 小把泡软\n热锅下油爆香虾皮\n下冬瓜翻炒 2 分钟，加小半碗水\n盖锅煮 5 分钟至冬瓜透明，加盐出锅", "默认池", "#粤菜家常"),
        Dish("紫菜蛋花汤", "晚餐", "汤", "淡", "十分钟滚一锅，解腻暖胃", 60, 10, "普通", "紫菜 1 小撮撕碎，鸡蛋 1 个打散\n水 3 碗加姜片煮开\n下紫菜煮 1 分钟，淋入蛋液成蛋花\n加盐、少许白胡椒，滴两滴香油，撒葱花", "默认池", "#粤菜家常"),
        Dish("玉米羹", "晚餐", "汤", "甜", "清甜暖胃，老少都爱", 130, 15, "普通", "玉米粒 1 碗（罐头或现剥）加 2 碗水打成浆\n倒锅加 1 碗水烧开\n淋入打散的蛋液成蛋花\n加盐少许、糖半勺调味，水淀粉勾薄芡", "默认池", "#粤菜家常"),
        Dish("咸蛋蒸肉饼", "中餐", "菜", "咸", "广式下饭肉饼，弹牙咸香", 300, 20, "普通", "猪肉末 3 两（半肥瘦）加生抽、糖、生粉、少许水，顺一个方向搅起胶\n咸蛋 1 只取蛋黄压碎，蛋白打入肉末一起搅匀\n肉末压成 1.5cm 厚饼平铺盘中\n大火蒸 15 分钟，出锅撒葱花", "默认池", "#粤菜家常"),
        Dish("清蒸红衫鱼", "晚餐", "菜", "鲜", "一条小鱼，蒸出来最鲜", 180, 15, "普通", "红衫鱼 1 条（约 300g）去鳞去内脏洗净，两面划几刀，抹盐腌 5 分钟\n鱼身下垫姜片，水开后大火蒸 8 分钟\n倒掉盘中腥水，铺新姜丝葱丝\n淋蒸鱼豉油，热油烧冒烟浇在葱丝上", "默认池", "#粤菜家常"),
        Dish("上汤娃娃菜", "晚餐", "菜", "鲜", "皮蛋咸蛋吊汤，鲜掉眉毛", 120, 15, "稀有", "娃娃菜 2 棵竖切四瓣，皮蛋 1 个、咸蛋 1 个切粒，蒜末少许\n热锅下油爆香蒜末，下皮蛋咸蛋略炒\n加水 1 碗煮开成奶白汤\n下娃娃菜煮 5 分钟至软，加盐调味", "默认池", "#粤菜家常"),
        Dish("栗子焖鸡", "晚餐", "菜", "香", "软糯栗子配鸡块，秋冬暖身", 420, 45, "稀有", "鸡半只斩块，冷水下锅加姜酒飞水冲净；栗子 10 颗去壳\n热锅下油爆姜片，下鸡块炒香\n加生抽、冰糖、水盖面，下栗子小火焖 30 分钟\n大火收汁至浓稠，撒葱花", "默认池", "#粤菜家常"),
        Dish("生滚牛肉粥", "早餐", "菜", "鲜", "牛肉一烫就熟，粥底滑得挂勺", 340, 50, "稀有", "米半杯洗净，加1小勺油和少许盐拌匀腌10分钟\\n水8碗烧开下米，大火滚5分钟转小火，锅盖留缝煮40分钟，中途搅几次锅底\\n牛肉2两逆纹切薄片，用生抽半勺、生粉1小勺、少许水、油抓匀腌10分钟\\n粥转大火，牛肉片抖散下锅煮40秒变色即关火\\n加盐和白胡椒，撒姜丝葱花", "默认池", "#广式早餐 #生滚粥"),
        Dish("鱼片粥", "早餐", "菜", "鲜", "鲩鱼片滑嫩，粥水清甜", 300, 50, "稀有", "粥底按白粥方法煮好（米半杯、水8碗、小火40分钟）\\n鲩鱼肉2两切双飞薄片，用盐、生粉、少许蛋白、油腌10分钟\\n粥转大火保持翻滚，鱼片逐片放下烫30秒变白\\n关火，加盐、白胡椒、姜丝、葱花，趁热吃", "默认池", "#广式粥 #鱼片粥"),
        Dish("艇仔粥", "早餐", "菜", "鲜", "料足的一碗，西关老味道", 380, 60, "史诗", "粥底煮好备用；瘦肉1两切丝、鱼片1两、虾仁5只分别用盐生粉腌10分钟\\n浮皮（炸猪皮）泡软切丝，鱿鱼干泡软切丝，花生米炸香，油条切碎\\n碗底先放浮皮丝和鱿鱼丝\\n粥转大火，依次下肉丝、鱼片、虾仁各煮40秒\\n热粥冲进碗里，撒花生、油条碎、葱花、白胡椒粉", "默认池", "#艇仔粥 #广州味道"),
        Dish("鲜虾云吞面", "早餐", "菜", "鲜", "一碗有汤有面有云吞", 520, 30, "史诗", "虾仁150g拍扁剁几刀，加猪肉末100g、盐、糖、生粉、白胡椒、麻油，顺一个方向搅到起胶，冷藏20分钟\\n云吞皮包入馅料，捏紧收口\\n汤底：水4碗加虾皮1勺、大地鱼粉1小勺、盐煮开，转小火保温\\n全蛋面1个饼煮散，过冷水沥干；云吞下锅煮3分钟浮起\\n碗中放面、云吞，冲入汤底，加韭黄段和几滴麻油", "默认池", "#云吞面 #广式面食"),
        Dish("牛腩捞面", "早餐", "菜", "咸", "牛腩汁拌面，一口满足", 560, 25, "稀有", "现成柱侯牛腩2两连汁加热备用（自己做见萝卜焖牛腩）\\n全蛋面1个饼煮散，过冷水后沥干\\n面拌半勺蚝油和1小勺熟油，防粘增香\\n面装碗，牛腩连汁浇上，配灼菜心几条", "默认池", "#牛腩面 #广式茶餐厅"),
        Dish("咸蛋瘦肉粥", "早餐", "菜", "鲜", "咸蛋黄化在粥里，香得很", 350, 50, "普通", "粥底煮好（米半杯、水8碗、小火40分钟）\\n瘦肉2两切片，用盐、生粉、油腌10分钟\\n咸蛋1个分开蛋黄蛋白，蛋黄压碎下粥煮5分钟煮出油\\n下肉片煮2分钟，再淋入蛋白搅成蛋花\\n加盐、白胡椒、葱花", "默认池", "#咸蛋粥 #广式早餐"),
        Dish("白灼菜心", "中餐", "菜", "淡", "一碟青菜，清清爽爽", 110, 8, "普通", "菜心300g洗净，粗梗划一刀\\n水开加1勺油和半小勺盐（保持翠绿）\\n菜心下锅灼40秒捞出摆盘\\n淋蒸鱼豉油1.5勺，铺蒜末，浇1勺烧到冒烟的热油", "默认池", "#白灼菜心 #广式家常"),
        Dish("腐乳通菜", "中餐", "菜", "咸", "腐乳一拌，通菜立刻有灵魂", 140, 8, "普通", "通菜300g洗净切段，梗和叶分开放\\n腐乳1块加半勺腐乳汁、少许糖压散调匀\\n热锅下油爆香蒜末，先下梗炒30秒\\n下叶子快炒到塌软，倒入腐乳汁兜匀即起", "默认池", "#腐乳通菜 #下饭"),
        Dish("滑蛋牛肉", "中餐", "菜", "鲜", "牛肉嫩蛋滑，茶餐厅经典", 320, 15, "普通", "牛肉2两逆纹切薄片，用生抽、糖、生粉、油腌10分钟\\n蛋3个加少许盐和1勺水打散\\n热锅宽油，牛肉炒到七成熟盛起\\n转小火倒蛋液，边推边炒，回牛肉，七成熟熄火用余温焖30秒", "默认池", "#滑蛋牛肉 #茶餐厅"),
        Dish("西兰花炒虾仁", "中餐", "菜", "鲜", "颜色好看，虾仁爽脆", 220, 12, "普通", "虾仁150g开背去虾线，用盐、生粉、少许蛋白腌10分钟\\n西兰花半个切小朵，水开加油盐焯1分钟捞出\\n热锅爆蒜末，虾仁炒到变色卷曲\\n下西兰花，加盐、蚝油半勺，生粉水勾薄芡兜匀", "默认池", "#西兰花炒虾仁 #快手菜"),
        Dish("莴笋虾仁炒蛋", "中餐", "菜", "鲜", "黄绿粉三色，清爽下饭", 260, 15, "普通", "虾仁150g用盐、生粉腌10分钟；蛋3个打散\\n莴笋1根去皮切薄片，水开焯30秒过凉水（保持翠绿脆口）\\n热锅炒蛋到刚凝固盛起\\n爆姜蒜下虾仁炒变色，下莴笋快炒，回蛋，加盐调味", "默认池", "#莴笋 #家常小炒"),
        Dish("五花肉炒青瓜", "中餐", "菜", "咸", "五花煸出油，青瓜吸味", 380, 15, "普通", "五花肉2两切薄片；青瓜2根切片，用少许盐腌5分钟挤干水\\n热锅不放油，下五花肉中小火煸到出油、边缘微焦\\n下蒜末和豆豉半勺炒香\\n下青瓜大火炒1分钟，加生抽1勺、蚝油半勺、糖少许兜匀", "默认池", "#五花肉炒青瓜 #下饭"),
        Dish("虎皮尖椒炒肥牛", "中餐", "菜", "辣", "尖椒焦香配肥牛，米饭杀手", 420, 15, "稀有", "尖椒4个拍一下切段；肥牛200g用厨房纸吸干水分\\n碗芡：生抽1勺、老抽半勺、蚝油1勺、糖半勺、生粉水少许\\n中小火煎尖椒，用铲子轻压，煎到起焦黄虎皮盛起\\n爆蒜末豆豉，下肥牛大火快炒变色，回尖椒，倒碗芡收汁", "默认池", "#虎皮尖椒 #肥牛"),
        Dish("咸鱼鸡粒炒饭", "中餐", "菜", "咸", "咸鱼香一炒，整锅饭都活了", 560, 20, "稀有", "隔夜饭2碗用手打散；鸡腿肉2两切粒，用生抽生粉腌10分钟\\n咸鱼1小块煎香，去骨撕碎\\n蛋2个炒散盛起\\n热锅爆咸鱼和鸡粒炒熟，下饭炒散压开\\n回蛋，加生抽半勺、葱花，大火兜匀起锅", "默认池", "#咸鱼鸡粒炒饭 #广式炒饭"),
        Dish("生炒牛肉饭", "中餐", "菜", "咸", "干身有镬气，粒粒分明", 580, 20, "稀有", "隔夜饭2碗打散；牛肉2两切片，用生抽、生粉、油腌10分钟\\n热锅宽油，牛肉快炒七成熟盛起\\n原锅下蛋2个炒散，立刻下饭，用铲压散炒到饭粒跳动\\n回牛肉，加生抽1勺、老抽少许、葱花，大火兜匀", "默认池", "#生炒牛肉饭 #镬气"),
        Dish("干炒牛河", "中餐", "菜", "香", "镬气足，河粉不断不烂", 620, 20, "史诗", "河粉300g用手轻轻抖散，别弄断\\n牛肉2两切片，用生抽、生粉、油腌10分钟；豆芽2两、韭黄段、洋葱丝备好\\n热锅宽油牛肉炒七成熟盛起\\n锅烧到冒烟下油，河粉摊开煎30秒再翻面，加老抽1勺、生抽1勺兜匀上色\\n下豆芽洋葱、牛肉、韭黄，大火快炒10秒即起", "默认池", "#干炒牛河 #粤菜必点"),
        Dish("豉椒炒蚬", "中餐", "菜", "鲜", "一碟蚬，配饭配酒都行", 240, 15, "稀有", "蚬1斤用盐水养2小时吐沙，洗净\\n水开下蚬煮到开口立刻捞出（没开的口扔掉）\\n爆蒜末、豆豉1勺、指天椒1只\\n下蚬大火炒，淋米酒、生抽1勺、糖少许，加葱段兜匀", "默认池", "#豉椒炒蚬 #大排档"),
        Dish("蒜蓉粉丝蒸扇贝", "中餐", "菜", "鲜", "粉丝吸汁，一口一个", 260, 20, "稀有", "扇贝6只刷净外壳，取出贝肉去内脏洗净\\n粉丝1小把泡软剪段，铺在壳底\\n蒜末半碗分两份：一份用油小火炒香，和生蒜末混合，加蚝油半勺、生抽1勺、糖少许拌成蒜蓉酱\\n扇贝肉放粉丝上，铺蒜蓉酱\\n水开大火蒸5分钟，撒葱花浇热油", "默认池", "#蒜蓉粉丝蒸扇贝 #宴客菜"),
        Dish("蒜蓉蒸丝瓜", "中餐", "菜", "淡", "清甜出水，夏天必备", 130, 12, "普通", "丝瓜1条去皮切3cm段，摆盘\\n蒜末2勺加少许油和盐拌匀\\n蒜末铺在丝瓜上\\n水开蒸6分钟，出锅淋几滴生抽、撒葱花", "默认池", "#蒜蓉蒸丝瓜 #清淡"),
        Dish("菜脯炒蛋", "中餐", "菜", "咸", "菜脯咸香，蛋滑", 280, 10, "普通", "菜脯（萝卜干）1两切碎，泡5分钟挤干水\\n蛋3个打散加少许糖\\n热锅下油炒香菜脯，炒到干身出香\\n倒蛋液，小火慢慢推炒到凝固", "默认池", "#菜脯炒蛋 #潮粤家常"),
        Dish("苦瓜炒蛋", "中餐", "菜", "苦", "先苦后甘，夏天降火", 240, 12, "普通", "苦瓜半条去瓤切薄片，用盐腌10分钟挤水（能减苦）\\n蛋3个打散\\n热锅炒蛋到半凝固盛起\\n爆蒜末下苦瓜炒2分钟，回蛋，加盐调味兜匀", "默认池", "#苦瓜炒蛋 #清热"),
        Dish("番茄牛肉", "中餐", "菜", "甜", "酸甜开胃，汁能拌饭", 360, 20, "普通", "牛肉2两逆纹切片，用生抽、糖、生粉、油腌10分钟\\n番茄2个切块\\n热锅宽油牛肉快炒七成熟盛起\\n下番茄炒出汁，加糖1勺、盐少许、水3勺煮3分钟\\n回牛肉，生粉水勾薄芡兜匀", "默认池", "#番茄牛肉 #开胃"),
        Dish("芥兰炒腊味", "中餐", "菜", "咸", "腊肠的油香裹住芥兰", 380, 15, "普通", "芥兰300g斜切段，水开加油盐焯1分钟捞出\\n腊肠1条蒸10分钟切斜片\\n热锅下腊肠煸出油\\n下蒜末、芥兰大火炒，加生抽半勺、糖少许兜匀", "默认池", "#芥兰炒腊肠 #广式"),
        Dish("腊肠炒荷兰豆", "中餐", "菜", "咸", "脆甜配咸香，十分钟上桌", 320, 12, "普通", "荷兰豆200g撕去两边的筋，水开焯30秒捞出\\n腊肠1条切片\\n热锅煸腊肠出油\\n下蒜末、荷兰豆大火炒1分钟，加盐和少许糖", "默认池", "#腊肠炒荷兰豆 #快手"),
        Dish("豆芽炒酸菜", "中餐", "菜", "酸", "酸咸爽脆，配粥绝配", 160, 10, "普通", "酸菜2两切碎，泡5分钟挤干\\n绿豆芽200g洗净沥干\\n热锅爆蒜末和辣椒\\n下酸菜炒香，再下豆芽大火炒1分钟，加少许糖和生抽", "默认池", "#豆芽炒酸菜 #开胃小菜"),
        Dish("盐油菠菜", "中餐", "菜", "淡", "两分钟一碟，最见功力", 110, 6, "普通", "菠菜400g去根洗净（根部容易藏泥）\\n水开加2勺花生油和1.5小勺盐\\n菠菜下锅烫40秒变软立刻捞出沥干装盘\\n铺姜丝，浇1勺烧热的油，喜咸可淋几滴生抽", "默认池", "#盐油菠菜 #广式清淡"),
        Dish("清蒸多宝鱼", "晚餐", "菜", "鲜", "肉质细嫩，八分钟出锅", 280, 20, "普通", "多宝鱼1条约1斤，去内脏洗净，两面各划3刀\\n盘底垫姜片葱段，鱼放上，鱼肚塞姜葱\\n水开后大火蒸8分钟，关火焖2分钟\\n倒掉盘中腥水，换新葱丝，淋蒸鱼豉油3勺\\n2勺油烧到冒烟浇在葱丝上", "默认池", "#清蒸多宝鱼 #粤菜"),
        Dish("姜葱蒸黄脚立", "晚餐", "菜", "鲜", "姜葱一蒸，鲜到眉毛掉", 260, 20, "稀有", "黄脚立1条约1斤，去鳞去腮去内脏，刮净腹内黑膜，两面划刀\\n鱼身抹薄盐，肚子塞姜片葱段，腌5分钟\\n盘底垫姜葱，鱼放上，水开大火蒸8-10分钟（筷子能插透即熟）\\n倒掉腥水，铺姜丝葱丝，浇热油，淋蒸鱼豉油2勺", "默认池", "#黄脚立 #清蒸海鱼"),
        Dish("煎葱蒸鱼腩", "晚餐", "菜", "鲜", "葱香浓，鱼腩滑", 340, 25, "稀有", "鲩鱼腩400g刮净黑膜，抹薄盐腌5分钟\\n香葱一半切段一半切花，姜切片和丝\\n盘底铺姜片葱段，放鱼腩，水开大火蒸6-8分钟\\n倒掉汤汁，铺姜丝葱花\\n2勺花生油烧到冒青烟浇上，再淋蒸鱼豉油2勺", "默认池", "#蒸鱼腩 #葱油"),
        Dish("豉汁蒸鱼头", "晚餐", "菜", "鲜", "豆豉压腥，鱼头滑", 320, 25, "稀有", "鱼头1个（约1斤）斩块，洗净沥干\\n豆豉1勺剁碎，加蒜末、姜末、生抽1勺、蚝油半勺、糖少许、生粉1勺、油1勺拌成豉汁\\n鱼头抓匀腌10分钟，平铺盘中\\n水开大火蒸10-12分钟，撒葱花和红椒圈", "默认池", "#豉汁蒸鱼头 #下饭"),
        Dish("砂锅鱼头煲", "晚餐", "菜", "香", "冬天一锅，热气腾腾", 480, 40, "史诗", "鱼头1个斩块，用盐、生抽、生粉、酒腌15分钟\\n砂锅烧热下油，爆香姜片、蒜粒、干葱头\\n下鱼头块煎到两面定型\\n加生抽1勺、蚝油1勺、柱侯酱半勺、水半碗，盖盖中火焖12分钟\\n下豆腐块或支竹再焖5分钟，撒葱段上桌", "默认池", "#砂锅鱼头煲 #冬日暖身"),
        Dish("啫啫鸡煲", "晚餐", "菜", "香", "砂锅滋滋响，沙姜香", 520, 35, "史诗", "鸡腿肉3只斩块，用米酒、生抽2勺、蚝油1勺、柱侯酱1勺、糖、白胡椒腌20分钟，最后加生粉1勺和1勺油封层\\n砂锅大火烧到冒烟，多下花生油，爆香沙姜、红葱头、姜蒜到微焦\\n鸡块平铺进锅，先别翻，大火煎1分钟再翻拌\\n盖盖沿锅边淋一圈米酒，大火焗5分钟\\n开盖下洋葱块和青红椒，翻拌再焗1分钟，撒香菜葱段端上桌", "默认池", "#啫啫鸡煲 #沙姜"),
        Dish("沙姜鸡", "晚餐", "菜", "香", "沙姜的辛香，广东独有", 420, 40, "稀有", "鸡半只洗净沥干，用盐和沙姜粉1勺里外抹匀，腌20分钟\\n水开上锅大火蒸20分钟，关火焖5分钟\\n沙姜30g剁蓉，加葱花、盐少许，浇2勺热花生油做蘸汁\\n鸡稍凉斩件，配沙姜蘸汁吃", "默认池", "#沙姜鸡 #粤西风味"),
        Dish("隔水蒸鸡", "晚餐", "菜", "鲜", "原汁原味，鸡味最浓", 400, 45, "史诗", "鸡半只洗净擦干，薄薄抹一层盐和花生油，肚子塞姜片葱段\\n蒸锅水大开后放鸡，大火蒸20分钟（1.4斤以上加3分钟）\\n关火焖5分钟再取出，盘里的原汤留着\\n斩件装盘，原汤淋回鸡肉上\\n蘸料：沙姜蓉加盐，浇热油", "默认池", "#隔水蒸鸡 #原味"),
        Dish("客家咸鸡", "晚餐", "菜", "咸", "咸香紧实，越嚼越香", 430, 90, "传说", "鸡半只洗净擦干，用粗盐2勺里外抹匀，冷藏腌6小时以上（过夜最好）\\n取出冲掉表面盐分，擦干，用纱布包好\\n蒸锅水开大火蒸25分钟，关火焖10分钟\\n放凉后斩件，肉质紧实咸香，配白粥一流", "默认池", "#客家咸鸡 #咸香"),
        Dish("豉油皇煎虾", "晚餐", "菜", "咸", "壳脆肉弹，连壳都能嚼", 300, 15, "稀有", "大虾8只剪须开背去虾线，用厨房纸吸干\\n调豉油皇：生抽1勺、老抽半勺、糖1小勺、水2勺、麻油几滴\\n热锅下油，虾平铺中火煎到两面变红出香\\n沿锅边淋豉油皇，快速兜匀收汁，撒葱花", "默认池", "#豉油皇煎虾 #宴客"),
        Dish("蒜蓉蒸虾", "晚餐", "菜", "鲜", "开背铺蒜，六分钟", 260, 18, "普通", "大虾8只剪须开背去虾线，背部切开摊平\\n蒜末3勺，一半用油小火炒香，和生蒜末混合，加少许盐和油拌成蒜蓉\\n虾平铺盘中，蒜蓉铺满虾背\\n水开大火蒸6分钟，淋生抽几滴，撒葱花浇热油", "默认池", "#蒜蓉蒸虾 #快手硬菜"),
        Dish("姜葱炒花甲", "晚餐", "菜", "鲜", "鲜辣带汁，配饭配酒", 260, 15, "普通", "花甲1斤盐水养2小时吐沙，洗净\\n水开下花甲煮到开口立刻捞出\\n热锅下油，爆大量姜片、葱白、蒜末、辣椒\\n下花甲大火炒，淋米酒、生抽1勺、蚝油半勺、糖少许，加葱绿兜匀", "默认池", "#姜葱炒花甲 #大排档"),
        Dish("豉汁炒鱿鱼", "晚餐", "菜", "鲜", "鱿鱼卷脆，豉香浓", 280, 15, "普通", "鲜鱿鱼1只撕去红膜、抽软骨、去内脏，内侧打十字花刀后切块\\n水开下鱿鱼焯10秒卷起立刻捞出\\n爆蒜末、豆豉1勺、姜丝\\n下鱿鱼大火快炒，加生抽1勺、蚝油半勺、糖少许，撒葱段起锅", "默认池", "#豉汁炒鱿鱼 #快炒"),
        Dish("韭菜炒鱿鱼", "晚餐", "菜", "鲜", "韭菜香配鱿鱼脆", 290, 15, "普通", "鱿鱼1只处理干净切圈或打花刀，焯水10秒捞出\\n韭菜3两洗净切段，梗叶分开\\n热锅下油爆姜丝，下鱿鱼快炒\\n先下韭菜梗炒20秒，再下叶子，加盐和少许生抽兜匀即起", "默认池", "#韭菜炒鱿鱼 #家常"),
        Dish("烧肉炒四季豆", "晚餐", "菜", "咸", "烧肉出油，四季豆入味", 420, 18, "普通", "四季豆250g撕筋掰段，水开加油盐焯3-4分钟至断生（一定要熟透）\\n烧肉200g切厚片\\n热锅不放油下烧肉煸出油、表面微焦\\n下姜蒜爆香，下四季豆大火炒，加生抽1勺、蚝油半勺、糖少许兜匀", "默认池", "#烧肉炒四季豆 #广式"),
        Dish("蜜汁鸡翅", "晚餐", "菜", "甜", "焦糖色，甜咸适口", 450, 30, "普通", "鸡中翅8只两面划刀，用生抽1勺、蚝油半勺、糖半勺、料酒腌20分钟\\n平底锅少油，中小火煎鸡翅两面金黄\\n加腌料和半碗水，盖锅焖8分钟\\n开盖加蜂蜜1勺大火收汁，收到酱汁挂满鸡翅", "默认池", "#蜜汁鸡翅 #小孩最爱"),
        Dish("鸡翅焖薯仔", "晚餐", "菜", "咸", "一锅焖，薯仔吸饱肉汁", 480, 30, "普通", "鸡中翅8只两面划刀，用盐、料酒、胡椒腌15分钟\\n薯仔1个切滚刀块，泡水防黑；菜花少许掰小朵\\n热锅煎鸡翅两面金黄，下姜蒜葱段爆香，下薯仔翻炒\\n加生抽2勺、老抽半勺、蚝油1勺、糖半勺、水没过一半，盖锅中火焖10分钟\\n下菜花再焖5分钟，大火收汁加盐调味", "默认池", "#鸡翅焖薯仔 #一锅出"),
        Dish("盐焗鸡中翅", "晚餐", "菜", "香", "盐焗粉一抹，电饭锅就行", 420, 40, "普通", "鸡中翅8只洗净划刀，用厨房纸吸干水分\\n盐焗鸡粉15g加少许油调匀，抹遍鸡翅，加姜片葱段腌2小时（过夜更入味）\\n电饭锅内胆刷油，铺姜片葱段，放鸡翅\\n按煮饭键，跳键后翻面再按一次，跳键即熟", "默认池", "#盐焗鸡翅 #电饭锅"),
        Dish("柱侯酱焖鸡", "晚餐", "菜", "香", "柱侯酱是粤菜焖东西的灵魂", 480, 40, "稀有", "鸡半只斩块，用生抽、生粉、油腌15分钟\\n热锅下油爆姜片、蒜粒、干葱头\\n下鸡块煎到表面金黄\\n加柱侯酱1.5勺、生抽1勺、冰糖1小块、水半碗，盖盖小火焖20分钟\\n大火收汁，撒葱段", "默认池", "#柱侯酱焖鸡 #粤菜"),
        Dish("冬菇焖鸡", "晚餐", "菜", "香", "冬菇香，鸡滑", 460, 45, "稀有", "干冬菇6朵温水泡软，泡菇水留着；鸡半只斩块腌15分钟\\n热锅爆姜片蒜粒，下鸡块煎金黄\\n下冬菇炒香，加生抽1.5勺、蚝油1勺、糖少许\\n倒入泡菇水加半碗清水，盖盖小火焖20分钟\\n大火收汁，撒葱段", "默认池", "#冬菇焖鸡 #家常硬菜"),
        Dish("客家酿苦瓜", "晚餐", "菜", "咸", "苦瓜圈酿肉，汤汁清甜", 340, 45, "稀有", "苦瓜1条切3cm圈，去瓤，水开焯1分钟（减苦）\\n猪肉末3两加盐、生抽、生粉、葱花，顺一个方向搅起胶\\n把肉馅酿进苦瓜圈，压平两面\\n平底锅少油，两面煎定型\\n加生抽1勺、水半碗，盖盖小火焖15分钟收汁", "默认池", "#酿苦瓜 #客家菜"),
        Dish("南瓜蒸排骨", "晚餐", "菜", "咸", "南瓜吸肉汁，甜咸交织", 400, 30, "普通", "排骨4两斩小块，冷水泡20分钟去血水，沥干\\n用豆豉1勺、蒜末、生抽1勺、糖、生粉1勺、油1勺抓匀腌15分钟\\n南瓜半个切厚片铺盘底\\n排骨铺在南瓜上，水开大火蒸18分钟，撒葱花", "默认池", "#南瓜蒸排骨 #一碟下饭"),
        Dish("腐竹焖鱼腩", "晚餐", "菜", "鲜", "腐竹吸满鱼汁", 420, 35, "稀有", "腐竹2条温水泡软切段；鱼腩400g洗净切块，用盐、生粉拍匀\\n热锅下油，鱼腩两面煎金黄盛起\\n爆姜片蒜粒，下腐竹略炒，加生抽1勺、蚝油1勺、糖少许、水半碗\\n回鱼腩，盖盖小火焖12分钟，收汁撒葱段", "默认池", "#腐竹焖鱼 #家常"),
        Dish("藕片炒肉", "晚餐", "菜", "咸", "藕片脆，肉片嫩", 340, 15, "普通", "莲藕1节去皮切薄片，泡水防氧化，水开焯1分钟\\n猪肉2两切片，用生抽、生粉、油腌10分钟\\n热锅下肉片炒变色盛起\\n爆蒜末下藕片大火炒，加生抽1勺、盐少许，回肉片兜匀", "默认池", "#藕片炒肉 #爽脆"),
        Dish("冬瓜焖鸭", "晚餐", "菜", "鲜", "冬瓜化在鸭汁里", 480, 60, "史诗", "鸭半只斩块，冷水下锅加姜葱酒飞水，冲净沥干\\n热锅不放油，下鸭块煸出油至表面金黄\\n下姜片、蒜粒、柱侯酱1勺、生抽1勺、冰糖炒匀\\n加水盖面，小火焖30分钟\\n下冬瓜块再焖15分钟至软，收汁撒葱段", "默认池", "#冬瓜焖鸭 #粤式焖菜"),
        Dish("咸鱼蒸肉饼", "晚餐", "菜", "咸", "咸鱼梅香，一碟两碗饭", 360, 25, "普通", "咸鱼1小块（约1两）蒸5分钟去骨撕碎\\n猪肉末3两（肥瘦3:7）加生抽、糖、生粉、水2勺，顺一个方向搅起胶\\n拌入咸鱼碎，压成1.5cm厚的饼\\n水开大火蒸12分钟，出锅淋几滴熟油、撒葱花", "默认池", "#咸鱼蒸肉饼 #下饭"),
        Dish("蒸三色蛋", "晚餐", "菜", "鲜", "皮蛋咸蛋鸡蛋，滑得像布丁", 280, 25, "普通", "皮蛋1个、咸蛋1个切小丁，鸡蛋2个打散\\n蛋液加温水（1:1.5）、少许盐和生抽打匀，过筛去泡\\n皮蛋咸蛋丁铺碗底，倒入蛋液，盖保鲜膜扎几个孔\\n水开中小火蒸12分钟，关火焖3分钟，淋生抽和麻油", "默认池", "#三色蛋 #蒸蛋"),
        Dish("豉汁蒸凤爪", "晚餐", "菜", "香", "茶楼味，家里也能做", 380, 60, "传说", "鸡爪10只剪指甲，冷水下锅焯5分钟捞出擦干\\n油烧到六成热，下鸡爪炸到表皮起皱（会溅油，盖锅盖），捞出立刻泡冰水1小时\\n豆豉1勺、蒜末、生抽1勺、蚝油1勺、糖、辣椒、生粉拌成豉汁\\n鸡爪抓匀腌20分钟，平铺盘中\\n水开大火蒸25分钟至软糯", "默认池", "#豉汁凤爪 #茶楼点心"),
        Dish("白切猪手", "晚餐", "菜", "鲜", "爽脆带胶质", 420, 90, "传说", "猪前蹄1只斩块，冷水下锅加姜葱酒飞水，冲净\\n锅中水加姜片葱段煮开，下猪手小火浸40分钟（保持微滚）\\n捞出立刻泡冰水20分钟，皮才爽脆\\n斩件装盘，配沙姜豉油蘸汁（沙姜蓉+生抽+热油）", "默认池", "#白切猪手 #爽脆"),
        Dish("姜醋猪脚", "晚餐", "菜", "酸", "酸甜胶质，冬天进补", 560, 120, "神话", "猪脚1只斩块飞水冲净；鸡蛋4个煮熟剥壳\\n甜醋1瓶加姜片（老姜200g拍扁）煮开\\n下猪脚小火煲60分钟\\n下鸡蛋再煲20分钟，关火焖一夜更入味（至少焖2小时）\\n吃前再煮开，酸甜浓稠", "默认池", "#姜醋猪脚 #坐月子菜"),
        Dish("花生鸡脚汤", "晚餐", "汤", "鲜", "胶质浓，煲给爱漂亮的人", 300, 90, "普通", "鸡脚8只剪指甲，冷水下锅焯水冲净\\n花生100g用热水泡15分钟，去衣汤更清\\n鸡脚、花生、姜3片、红枣4颗入锅，加水8碗\\n大火滚后转小火煲1.5小时，出锅前10分钟加盐", "默认池", "#花生鸡脚汤 #胶质"),
